bject":"Venus","difficulty":"easy","source":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/","verified":"2026-10-03","sources":["https://nssdc.gsfc.nasa.gov/planetary/factsheet/"]}},{"id":"approved-20261003-8cd3ccb11c4b43f8270fa745","game":"facts","payload":{"s":"Neptun braucht länger als die Erde für einen Umlauf um die Sonne.","a":true,"e":"Neptuns Umlauf dauert ungefähr 59.800 Erdtage.","cat":"Weltraum","subject":"Neptun","difficulty":"easy","source":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/","verified":"2026-10-03","sources":["https://nssdc.gsfc.nasa.gov/planetary/factsheet/"]}},{"id":"approved-20261003-0c399b4832150cb091e4667e","game":"facts","payload":{"s":"Merkur braucht ungefähr ein Erdjahr für einen Umlauf um die Sonne.","a":false,"e":"Ein Merkurjahr dauert nur etwa 88 Erdtage.","cat":"Weltraum","subject":"Merkur","difficulty":"easy","source":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/","verified":"2026-10-03","sources":["https://nssdc.gsfc.nasa.gov/planetary/factsheet/"]}},{"id":"approved-20261003-bbfcd773f0bceb4572a72476","game":"facts","payload":{"s":"Yellowstone wurde 1872 als Nationalpark gegründet.","a":true,"e":"Das ist das Jahr der gesetzlichen Ausweisung als Nationalpark.","cat":"Natur","subject":"Yellowstone-Nationalpark","difficulty":"easy","source":"https://www.nps.gov/yell/planyourvisit/parkfacts.htm","verified":"2026-10-03","sources":["https://www.nps.gov/yell/planyourvisit/parkfacts.htm"]}},{"id":"approved-20261003-f844aa12e310a9c6e14abdb6","game":"facts","payload":{"s":"Zion erhielt bereits 1909 den Status eines Nationalparks.","a":false,"e":"1909 war es ein National Monument; der Nationalparkstatus folgte 1919.","cat":"Natur","subject":"Zion-Nationalpark","difficulty":"easy","source":"https://www.nps.gov/zion/learn/historyculture/people.htm","verified":"2026-10-03","sources":["https://www.nps.gov/zion/learn/historyculture/people.htm"]}},{"id":"approved-20261003-7b1039c2f75cd81acc033bd9","game":"facts","payload":{"s":"Olympic wurde 1938 als Nationalpark ausgewiesen.","a":true,"e":"Ein früherer Schutzstatus als National Monument ist davon zu unterscheiden.","cat":"Natur","subject":"Olympic-Nationalpark","difficulty":"easy","source":"https://www.nps.gov/olym/learn/historyculture/index.htm","verified":"2026-10-03","sources":["https://www.nps.gov/olym/learn/historyculture/index.htm"]}},{"id":"approved-20261003-eee5d9e270a4555ecc57af58","game":"facts","payload":{"s":"Yosemite wurde im selben Jahr wie Yellowstone als Nationalpark gegründet.","a":false,"e":"Yosemite wurde 1890 Nationalpark; Yellowstone 1872.","cat":"Natur","subject":"Yosemite-Nationalpark","difficulty":"easy","source":"https://www.nps.gov/yose/learn/news/yosemite-national-park-commemorates-124th-anniversary.htm","verified":"2026-10-03","sources":["https://www.nps.gov/yose/learn/news/yosemite-national-park-commemorates-124th-anniversary.htm"]}},{"id":"approved-20261003-32d9c8af93b62091bd10c965","game":"facts","payload":{"s":"Ein Standard-Kartendeck ohne Joker enthält 52 Karten.","a":true,"e":"Gezählt wird das vollständige Standarddeck ohne Joker.","cat":"Allgemeinwissen","subject":"Standard-Kartendeck ohne Joker","difficulty":"easy","source":"https://de.bicyclecards.com/game-rules/spades/","verified":"2026-10-03","sources":["https://de.bicyclecards.com/game-rules/spades/"]}},{"id":"approved-20261003-5fc59e085b090cebaa635d40","game":"facts","payload":{"s":"Das SET-Grundspiel enthält genauso viele Karten wie ein Standarddeck ohne Joker.","a":false,"e":"SET enthält 81 Karten; das Standarddeck 52.","cat":"Allgemeinwissen","subject":"SET (Grundspiel)","difficulty":"easy","source":"https://www.setgame.com/sites/default/files/set_catalogsmall.pdf","verified":"2026-10-03","sources":["https://www.setgame.com/sites/default/files/set_catalogsmall.pdf"]}},{"id":"approved-20261003-888076692af1e21142c733b8","game":"facts","payload":{"s":"Der Aachener Dom wurde 1978 erstmals UNESCO-Welterbe.","a":true,"e":"Die UNESCO nennt 1978 als Einschreibungsjahr.","cat":"Weltkultur","subject":"Aachener Dom","difficulty":"medium","source":"https://whc.unesco.org/en/list/3/","verified":"2026-10-03","sources":["https://whc.unesco.org/en/list/3/"]}},{"id":"approved-20261003-ee96177fe40378029f411612","game":"facts","payload":{"s":"Der Kölner Dom wurde früher UNESCO-Welterbe als der Aachener Dom.","a":false,"e":"Köln wurde 1996 eingeschrieben, Aachen bereits 1978.","cat":"Weltkultur","subject":"Kölner Dom","difficulty":"medium","source":"https://whc.unesco.org/en/list/292/","verified":"2026-10-03","sources":["https://whc.unesco.org/en/list/292/"]}},{"id":"approved-20261003-cd8eadad17c33d5abef9f572","game":"facts","payload":{"s":"Das Opernhaus Sydney wurde 2007 UNESCO-Welterbe.","a":true,"e":"2007 bezeichnet die Einschreibung, nicht die Eröffnung.","cat":"Weltkultur","subject":"Opernhaus Sydney","difficulty":"medium","source":"https://whc.unesco.org/en/list/166/","verified":"2026-10-03","sources":["https://whc.unesco.org/en/list/166/"]}},{"id":"approved-20261003-56165e1069a1406596098211","game":"facts","payload":{"s":"Das Opernhaus Sydney wurde erst in seinem UNESCO-Einschreibungsjahr 2007 eröffnet.","a":false,"e":"Es wurde 1973 eröffnet und erst 2007 eingeschrieben.","cat":"Weltkultur","subject":"Opernhaus Sydney","difficulty":"medium","source":"https://whc.unesco.org/en/list/166/","verified":"2026-10-03","sources":["https://whc.unesco.org/en/list/166/","https://www.sydneyoperahouse.com/our-story/50-years-extraordinary-moments"]}},{"id":"approved-20261003-aca700c9bb5221f350865c87","game":"facts","payload":{"s":"Das Taj Mahal wurde 1983 in die UNESCO-Welterbeliste aufgenommen.","a":true,"e":"Die Einschreibung erfolgte 1983.","cat":"Weltkultur","subject":"Taj Mahal","difficulty":"medium","source":"https://whc.unesco.org/en/list/252/","verified":"2026-10-03","sources":["https://whc.unesco.org/en/list/252/"]}},{"id":"approved-20261003-015510c740b2621be719d053","game":"facts","payload":{"s":"Das UNESCO-Einschreibungsjahr 1983 ist auch das Baujahr des Taj Mahal.","a":false,"e":"Das Bauwerk stammt aus dem 17. Jahrhundert; UNESCO-Einschreibung und Bauzeit sind verschieden.","cat":"Weltkultur","subject":"Taj Mahal","difficulty":"medium","source":"https://whc.unesco.org/en/list/252/","verified":"2026-10-03","sources":["https://whc.unesco.org/en/list/252/","https://whc.unesco.org/en/list/252/"]}},{"id":"approved-20261003-314a90f0642f3626dbb08083","game":"facts","payload":{"s":"Das James-Webb-Weltraumteleskop startete 2021 von der Erde.","a":true,"e":"Gemeint ist der Missionsstart, nicht die Aufnahme des wissenschaftlichen Betriebs.","cat":"Raumfahrt","subject":"James-Webb-Weltraumteleskop","difficulty":"medium","source":"https://science.nasa.gov/mission/webb/launch/","verified":"2026-10-03","sources":["https://science.nasa.gov/mission/webb/launch/"]}},{"id":"approved-20261003-418f989dfc57099618c386be","game":"facts","payload":{"s":"Hubble startete im selben Jahr wie das James-Webb-Weltraumteleskop.","a":false,"e":"Hubble startete 1990, Webb 2021.","cat":"Raumfahrt","subject":"Hubble-Weltraumteleskop","difficulty":"medium","source":"https://www.nasa.gov/history/hubble/","verified":"2026-10-03","sources":["https://www.nasa.gov/history/hubble/"]}},{"id":"approved-20261003-610ee8159d3133f5bfc84c48","game":"facts","payload":{"s":"Cassini-Huygens startete 1997.","a":true,"e":"Die Mission hob im Oktober 1997 ab.","cat":"Raumfahrt","subject":"Cassini-Huygens","difficulty":"medium","source":"https://science.nasa.gov/mission/cassini/quick-facts/","verified":"2026-10-03","sources":["https://science.nasa.gov/mission/cassini/quick-facts/"]}},{"id":"approved-20261003-e6633ce91d526bec7eb34f59","game":"facts","payload":{"s":"Voyager 1 startete erst 2006 von der Erde.","a":false,"e":"Voyager 1 startete 1977; New Horizons startete 2006.","cat":"Raumfahrt","subject":"Voyager 1","difficulty":"medium","source":"https://voyager.gsfc.nasa.gov/mission.html","verified":"2026-10-03","sources":["https://voyager.gsfc.nasa.gov/mission.html"]}},{"id":"approved-20261003-16d4f18a61e3dc26662b8620","game":"facts","payload":{"s":"Der Porsche 911 GT3 (PDK, 2025) hat einen Sechszylinder-Verbrennungsmotor.","a":true,"e":"Der GT3 verwendet einen Sechszylinder-Boxermotor.","cat":"Autos","subject":"Porsche 911 GT3 (PDK, 2025)","difficulty":"medium","source":"https://newsroom.porsche.com/en/2024/products/porsche-the-new-911-gt3-double-premiere-37595.html","verified":"2026-10-03","sources":["https://newsroom.porsche.com/en/2024/products/porsche-the-new-911-gt3-double-premiere-37595.html"]}},{"id":"approved-20261003-5c7e27e67a1559b9549f2672","game":"facts","payload":{"s":"Der Ferrari 296 GTB besitzt einen Achtzylinder-Verbrennungsmotor.","a":false,"e":"Der Verbrennungsmotor hat sechs Zylinder; der zusätzliche Elektromotor ändert diese Zylinderzahl nicht.","cat":"Autos","subject":"Ferrari 296 GTB","difficulty":"medium","source":"https://www.ferrari.com/content/dam/ferrari-fcom/old/pdf/CS_296_GTB_final_gbr.pdf","verified":"2026-10-03","sources":["https://www.ferrari.com/content/dam/ferrari-fcom/old/pdf/CS_296_GTB_final_gbr.pdf"]}},{"id":"approved-20261003-271495fdc08b7b1b59d20242","game":"facts","payload":{"s":"Der Verbrennungsmotor des Ferrari SF90 Stradale hat acht Zylinder.","a":true,"e":"Es ist ein V8 innerhalb des Hybridantriebs.","cat":"Autos","subject":"Ferrari SF90 Stradale","difficulty":"medium","source":"https://cdn.ferrari.com/cms/network/media/pdf/pr_ferrari_sf90_stradale_gbr.pdf","verified":"2026-10-03","sources":["https://cdn.ferrari.com/cms/network/media/pdf/pr_ferrari_sf90_stradale_gbr.pdf"]}},{"id":"approved-20261003-eaa502d7991da9ad6473ce06","game":"facts","payload":{"s":"Der Ferrari 12Cilindri kommt ohne Verbrennungsmotor aus.","a":false,"e":"Das Modell hat einen Zwölfzylinder-Verbrennungsmotor.","cat":"Autos","subject":"Ferrari 12Cilindri","difficulty":"medium","source":"https://www.ferrari.com/content/dam/ferrari-fcom/news/corporate/2026/01/pdf/CS_12Cilindri_Tailor_Made_gbr.pdf","verified":"2026-10-03","sources":["https://www.ferrari.com/content/dam/ferrari-fcom/news/corporate/2026/01/pdf/CS_12Cilindri_Tailor_Made_gbr.pdf"]}},{"id":"approved-20261003-66081df1b7371c8abda7a938","game":"facts","payload":{"s":"Mohamed Salah wurde 1992 geboren.","a":true,"e":"Sein Geburtsdatum ist der 15. Juni 1992.","cat":"Fußballer","subject":"Mohamed Salah","difficulty":"medium","source":"https://www.liverpoolfc.com/news/first-team/283441-mohamed-salah-in-the-beginning","verified":"2026-10-03","sources":["https://www.liverpoolfc.com/news/first-team/283441-mohamed-salah-in-the-beginning"]}},{"id":"approved-20261003-6537191e31ac2c2e461eddaa","game":"facts","payload":{"s":"Kylian Mbappé wurde im Jahr 2000 geboren.","a":false,"e":"Mbappé wurde 1998 geboren.","cat":"Fußballer","subject":"Kylian Mbappé","difficulty":"medium","source":"https://www.realmadrid.com/de-DE/fussball/erste-mannshaft/spieler/kylian-mbappe","verified":"2026-10-03","sources":["https://www.realmadrid.com/de-DE/fussball/erste-mannshaft/spieler/kylian-mbappe"]}},{"id":"approved-20261003-3813b1af203c785e2a5a7e31","game":"facts","payload":{"s":"Erling Haaland wurde früher geboren als Jude Bellingham.","a":true,"e":"Haaland wurde 2000 geboren, Bellingham 2003.","cat":"Fußballer","subject":"Erling Haaland","difficulty":"medium","source":"https://live.mancity.com/news/mens/erling-haaland-10-things-factfile-63790703","verified":"2026-10-03","sources":["https://live.mancity.com/news/mens/erling-haaland-10-things-factfile-63790703"]}},{"id":"approved-20261003-10a94816b2814587eb87e1d3","game":"facts","payload":{"s":"Jude Bellingham wurde 1998 geboren.","a":false,"e":"Bellingham wurde 2003 geboren.","cat":"Fußballer","subject":"Jude Bellingham","difficulty":"medium","source":"https://www.realmadrid.com/de-DE/fussball/erste-mannshaft/spieler/jude-bellingham","verified":"2026-10-03","sources":["https://www.realmadrid.com/de-DE/fussball/erste-mannshaft/spieler/jude-bellingham"]}},{"id":"approved-20261003-94e431af6e0444e07bc4baf0","game":"facts","payload":{"s":"Berlin ist in zwölf Verwaltungsbezirke gegliedert.","a":true,"e":"Die zwölf Bezirke sind die hier gezählte Verwaltungsebene.","cat":"Städte","subject":"Berlin","difficulty":"medium","source":"https://willkommenszentrum.berlin.de/glossary/bezirk","verified":"2026-10-03","sources":["https://willkommenszentrum.berlin.de/glossary/bezirk"]}},{"id":"approved-20261003-738fd1b731649e73447316b4","game":"facts","payload":{"s":"Wien hat ebenso wie Berlin zwölf Stadtbezirke.","a":false,"e":"Wien hat 23 Bezirke, Berlin zwölf.","cat":"Städte","subject":"Wien","difficulty":"medium","source":"https://www.wien.gv.at/statistik/bezirksdaten","verified":"2026-10-03","sources":["https://www.wien.gv.at/statistik/bezirksdaten"]}},{"id":"approved-20261003-61ef7bbd1aac53db982863d8","game":"facts","payload":{"s":"Ein Natrium-Atomkern enthält elf Protonen.","a":true,"e":"Natrium hat die Ordnungszahl 11.","cat":"Wissenschaft","subject":"Natrium","difficulty":"hard","source":"https://periodic-table.rsc.org/element/11/sodium","verified":"2026-10-03","sources":["https://periodic-table.rsc.org/element/11/sodium"]}}]$daily_batch$::jsonb) as x(id text,game text,payload jsonb)), inserted as (insert into ml_private.daily_catalogue(id,game,payload,available_from) select i.id,i.game,i.payload,date '2026-10-04' from incoming i where not exists(select 1 from ml_private.daily_catalogue old where old.game=i.game and ((i.game='moreless' and old.payload->>'u'=i.payload->>'u' and ((old.payload->>'l'=i.payload->>'l' and old.payload->>'r'=i.payload->>'r' and old.payload->'lv'=i.payload->'lv' and old.payload->'rv'=i.payload->'rv') or (old.payload->>'r'=i.payload->>'l' and old.payload->>'l'=i.payload->>'r' and old.payload->'rv'=i.payload->'lv' and old.payload->'lv'=i.payload->'rv'))) or (i.game='estimate' and old.payload->>'q'=i.payload->>'q') or (i.game='facts' and old.payload->>'s'=i.payload->>'s'))) on conflict(id) do nothing returning game) select game,count(*) as inserted from inserted group by game;
