c-table.rsc.org/element/20/calcium"]}},{"id":"approved-20261003-f4a9171d1e5019d1079ecd26","game":"facts","payload":{"s":"Ein Eisen-Atomkern enthält 26 Protonen.","a":true,"e":"Eisen hat die Ordnungszahl 26.","cat":"Wissenschaft","subject":"Eisen","difficulty":"hard","source":"https://periodic-table.rsc.org/element/26/iron","verified":"2026-10-03","sources":["https://periodic-table.rsc.org/element/26/iron"]}},{"id":"approved-20261003-2a73dcce96d990ed7d6bea4c","game":"facts","payload":{"s":"Silizium hat dieselbe Ordnungszahl wie Eisen.","a":false,"e":"Silizium hat die Ordnungszahl 14; Eisen 26.","cat":"Wissenschaft","subject":"Silizium","difficulty":"hard","source":"https://periodic-table.rsc.org/element/14/silicon","verified":"2026-10-03","sources":["https://periodic-table.rsc.org/element/14/silicon"]}},{"id":"approved-20261003-1586da1cbca0238b51e4db8c","game":"facts","payload":{"s":"Schwefel hat die Ordnungszahl 16.","a":true,"e":"Schwefel-Atomkerne enthalten 16 Protonen.","cat":"Wissenschaft","subject":"Schwefel","difficulty":"hard","source":"https://periodic-table.rsc.org/element/16/sulfur","verified":"2026-10-03","sources":["https://periodic-table.rsc.org/element/16/sulfur"]}},{"id":"approved-20261003-2939dd0404344ba8775882db","game":"facts","payload":{"s":"Ein Neon-Atomkern enthält elf Protonen.","a":false,"e":"Neon enthält zehn Protonen; Natrium elf.","cat":"Wissenschaft","subject":"Neon","difficulty":"hard","source":"https://periodic-table.rsc.org/element/10/neon","verified":"2026-10-03","sources":["https://periodic-table.rsc.org/element/10/neon"]}},{"id":"approved-20261003-bcda6ba479d42a834137914a","game":"facts","payload":{"s":"Der NASA-Temperaturwert für Jupiter von ungefähr −110 °C bezieht sich auf die Atmosphäre bei einem Druck von 1 bar.","a":true,"e":"Gasriesen werden in dieser Tabelle am 1-bar-Niveau verglichen, nicht an einer festen Oberfläche.","cat":"Weltraum","subject":"Jupiter","difficulty":"hard","source":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/","verified":"2026-10-03","sources":["https://nssdc.gsfc.nasa.gov/planetary/factsheet/","https://nssdc.gsfc.nasa.gov/planetary/factsheet/planetfact_notes.html"]}},{"id":"approved-20261003-e450e3f860453a37ea34e74d","game":"facts","payload":{"s":"Der NASA-Tabellenwert von ungefähr −140 °C für Saturn beschreibt die Temperatur seines Kerns.","a":false,"e":"Er bezieht sich auf das 1-bar-Niveau in der Atmosphäre, nicht auf den Kern.","cat":"Weltraum","subject":"Saturn","difficulty":"hard","source":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/","verified":"2026-10-03","sources":["https://nssdc.gsfc.nasa.gov/planetary/factsheet/","https://nssdc.gsfc.nasa.gov/planetary/factsheet/planetfact_notes.html"]}},{"id":"approved-20261003-fca7471590d1a98dce661213","game":"facts","payload":{"s":"Die NASA-Tabelle nennt für Neptuns mittlere Sonnenentfernung ungefähr 4.515 Millionen Kilometer.","a":true,"e":"Das sind etwa 4,515 Milliarden Kilometer; gemeint ist die große Halbachse.","cat":"Weltraum","subject":"Neptun","difficulty":"hard","source":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/","verified":"2026-10-03","sources":["https://nssdc.gsfc.nasa.gov/planetary/factsheet/"]}},{"id":"approved-20261003-09787f683df472eb09e41051","game":"facts","payload":{"s":"Der NASA-Wert zur mittleren Sonnenentfernung der Erde beschreibt ihre Entfernung zu jedem beliebigen Zeitpunkt exakt.","a":false,"e":"Die Entfernung schwankt auf der elliptischen Bahn; der Tabellenwert beschreibt die große Halbachse.","cat":"Weltraum","subject":"Erde","difficulty":"hard","source":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/","verified":"2026-10-03","sources":["https://nssdc.gsfc.nasa.gov/planetary/factsheet/","https://nssdc.gsfc.nasa.gov/planetary/factsheet/planetfact_notes.html"]}},{"id":"approved-20261003-31bf38a61d168575f89f87fc","game":"facts","payload":{"s":"Der NASA-Wert von ungefähr 464 °C für Venus ist eine mittlere Oberflächentemperatur.","a":true,"e":"Es handelt sich um einen mittleren Referenzwert und nicht um eine lokale Tageshöchsttemperatur.","cat":"Weltraum","subject":"Venus","difficulty":"hard","source":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/","verified":"2026-10-03","sources":["https://nssdc.gsfc.nasa.gov/planetary/factsheet/","https://nssdc.gsfc.nasa.gov/planetary/factsheet/planetfact_notes.html"]}},{"id":"approved-20261003-32a99cf5058e324c717da907","game":"facts","payload":{"s":"Die ungefähr 167 °C aus der NASA-Tabelle sind die maximale Tagestemperatur auf Merkur.","a":false,"e":"167 °C ist der mittlere Wert über die Oberfläche; lokale Tagestemperaturen können deutlich höher sein.","cat":"Weltraum","subject":"Merkur","difficulty":"hard","source":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/","verified":"2026-10-03","sources":["https://nssdc.gsfc.nasa.gov/planetary/factsheet/","https://nssdc.gsfc.nasa.gov/planetary/factsheet/planetfact_notes.html"]}},{"id":"approved-20261003-eed8fc6973b97951978ef93f","game":"facts","payload":{"s":"New Horizons startete früher von der Erde als das James-Webb-Weltraumteleskop.","a":true,"e":"New Horizons startete 2006, Webb 2021.","cat":"Raumfahrt","subject":"New Horizons","difficulty":"hard","source":"https://science.nasa.gov/mission/new-horizons/","verified":"2026-10-03","sources":["https://science.nasa.gov/mission/new-horizons/"]}},{"id":"approved-20261003-ca31420399122bf63a9bba17","game":"facts","payload":{"s":"Voyager 1 startete später als Hubble.","a":false,"e":"Voyager 1 startete 1977, Hubble 1990.","cat":"Raumfahrt","subject":"Voyager 1","difficulty":"hard","source":"https://voyager.gsfc.nasa.gov/mission.html","verified":"2026-10-03","sources":["https://voyager.gsfc.nasa.gov/mission.html"]}},{"id":"approved-20261003-264c4d1325fa598aa87cd314","game":"facts","payload":{"s":"Rocky Mountain wurde früher als Zion als Nationalpark ausgewiesen.","a":true,"e":"Rocky Mountain wurde 1915 Nationalpark, Zion 1919.","cat":"Natur","subject":"Rocky-Mountain-Nationalpark","difficulty":"hard","source":"https://www.nps.gov/romo/learn/historyculture/brief.htm","verified":"2026-10-03","sources":["https://www.nps.gov/romo/learn/historyculture/brief.htm"]}},{"id":"approved-20261003-a73bd7d836e9b2db3852e88c","game":"facts","payload":{"s":"Olympic erhielt schon 1909 den Status eines Nationalparks.","a":false,"e":"1909 war es ein National Monument; die Ausweisung als Nationalpark erfolgte 1938.","cat":"Natur","subject":"Olympic-Nationalpark","difficulty":"hard","source":"https://www.nps.gov/olym/learn/historyculture/index.htm","verified":"2026-10-03","sources":["https://www.nps.gov/olym/learn/historyculture/index.htm"]}}]$daily_batch$::jsonb) as x(id text,game text,payload jsonb)), inserted as (insert into ml_private.daily_catalogue(id,game,payload,available_from) select i.id,i.game,i.payload,date '2026-10-04' from incoming i where not exists(select 1 from ml_private.daily_catalogue old where old.game=i.game and ((i.game='moreless' and old.payload->>'u'=i.payload->>'u' and ((old.payload->>'l'=i.payload->>'l' and old.payload->>'r'=i.payload->>'r' and old.payload->'lv'=i.payload->'lv' and old.payload->'rv'=i.payload->'rv') or (old.payload->>'r'=i.payload->>'l' and old.payload->>'l'=i.payload->>'r' and old.payload->'rv'=i.payload->'lv' and old.payload->'lv'=i.payload->'rv'))) or (i.game='estimate' and old.payload->>'q'=i.payload->>'q') or (i.game='facts' and old.payload->>'s'=i.payload->>'s'))) on conflict(id) do nothing returning game) select game,count(*) as inserted from inserted group by game;
